 * Types for the Qwen Code CLI transcript integration.
 *
 * Qwen Code records each coding-agent session as a JSONL transcript where
 * every line is a `ChatRecord`. Records are linked into a conversation tree
 * via `uuid` / `parentUuid` and carry Gemini-style message `parts`.
 *
 * The transcript mixes several record kinds (user prompts, assistant turns,
 * tool results) distinguished by the `type` field.
 */

/**
 * A Gemini text part. `thought` marks internal reasoning that should be
 * hidden from user-facing text by default.
 */
export interface TextPart {
  text: string;
  thought?: boolean;
}

/**
 * A Gemini function-call part — the model requesting a tool invocation.
 */
export interface FunctionCallPart {
  functionCall: {
    id: string;
    name: string;
    args?: Record<string, any>;
  };
}

/**
 * A Gemini function-response part — the result of a tool invocation fed back
 * to the model.
 */
export interface FunctionResponsePart {
  functionResponse: {
    id: string;
    name: string;
    response: any;
  };
}

/**
 * Union of the message part shapes that can appear in a `ChatRecord` message.
 */
export type GeminiPart = TextPart | FunctionCallPart | FunctionResponsePart;

/**
 * Structured message body: a role plus an ordered array of parts.
 */
export interface GeminiMessage {
  role: string;
  parts: GeminiPart[];
}

/**
 * Result of a tool call, attached to `tool_result` records.
 */
export interface ToolCallResult {
  callId: string;
  status: string;
  resultDisplay?: any;
}

/**
 * Token accounting emitted alongside assistant records.
 */
export interface UsageMetadata {
  promptTokenCount: number;
  candidatesTokenCount: number;
  totalTokenCount: number;
}

/**
 * A single line in a Qwen Code transcript JSONL file.
 */
export interface ChatRecord {
  uuid: string;
  parentUuid: string | null;
  sessionId: string;
  timestamp: string;
  type: 'user' | 'assistant' | 'system' | 'tool_result';
  message?: GeminiMessage | string;
  toolCallResult?: ToolCallResult;
  usageMetadata?: UsageMetadata;
  model?: string;
}

/**
 * OpenAI chat-format tool call, used on assistant messages in LLM span inputs.
 */
export interface ToolCall {
  id: string;
  type: 'function';
  function: {
    name: string;
    arguments: string;
  };
}

/**
 * OpenAI chat-format message used to reconstruct conversation history for
 * LLM span inputs. Matches the structure the MLflow UI Chat view renders.
