 * MLflow tracing integration for Qwen Code.
 *
 * Reads a Qwen Code JSONL session transcript and converts it into an MLflow
 * trace: an AGENT root span for the conversation, one LLM span per assistant
 * record, and one TOOL span per functionCall the assistant emits.
 *
 * Timing model (all in nanoseconds):
 * - Root span brackets the whole conversation: first user record -> last
 *   assistant record.
 * - Each LLM span covers "LLM thinking": from the preceding record to the
 *   assistant record it produced.
 * - Each TOOL span covers the tool invocation: from the assistant record that
 *   emitted the call to the matching tool_result record.
 */

import {
  startSpan,
  flushTraces,
  InMemoryTraceManager,
  SpanStatusCode,
  SpanType,
  SpanAttributeKey,
  TraceMetadataKey,
  TokenUsageKey,
} from '@mlflow/core';

import type { ChatRecord, OpenAIMessage } from './types.js';
import {
  readTranscript,
  parseTimestampToNs,
  getMessageText,
  getFunctionCalls,
  getToolOutput,
  getTokenUsage,
  buildToolResultMap,
