/**
 * Reconstruct OpenAI chat-format message history from the records preceding
 * `targetIndex`. Used to populate LLM span inputs so the MLflow Chat view
 * shows the conversation context that led up to each assistant call.
 *
 * - user records -> { role: 'user', content }
 * - assistant records with only text -> { role: 'assistant', content }
 * - assistant records with functionCall parts -> { role: 'assistant',
 *   content: null, tool_calls: [...] }
 * - tool_result records -> { role: 'tool', tool_call_id, content }
 * - system records with a message -> { role: 'system', content }
 * - system records without a message are skipped
 */
export function reconstructMessages(records: ChatRecord[], targetIndex: number): OpenAIMessage[] {
  const messages: OpenAIMessage[] = [];

  for (let i = 0; i < targetIndex; i++) {
    const record = records[i];

    if (record.type === 'user') {
      messages.push({ role: 'user', content: getMessageText(record) });
    } else if (record.type === 'assistant') {
      const functionCalls = getFunctionCalls(record);
      if (functionCalls.length > 0) {
        messages.push({
          role: 'assistant',
          content: null,
          tool_calls: functionCalls.map((fc) => ({
            id: fc.id,
            type: 'function' as const,
            function: { name: fc.name, arguments: JSON.stringify(fc.args ?? {}) },
          })),
