M,CAAC,aAAa,CAAC,aAAa,CAAC,sBAAsB,CAAC,CAAC,CAAC,IAAI,CAAC,QAAQ,CAAC,CAAC;QAC3E,MAAM,CAAC,aAAa,CAAC,aAAa,CAAC,mBAAmB,CAAC,CAAC,CAAC,WAAW,EAAE,CAAC;QACvE,MAAM,CAAC,kBAAW,CAAC,CAAC,gBAAgB,EAAE,CAAC;IACzC,CAAC,CAAC,CAAC;IAEH,EAAE,CAAC,2BAA2B,EAAE,KAAK,IAAI,EAAE;QACzC,MAAM,SAAS,GAAiB;YAC9B,OAAO,CAAC,CAAC,CAAC,EAAE,OAAO,CAAC,CAAC,CAAC;YACtB,EAAE,GAAG,OAAO,CAAC,CAAC,CAAC,EAAE,cAAc,EAAE,EAAE,MAAM,EAAE,IAAI,EAAE,MAAM,EAAE,WAAW,EAAE,EAAE;SACzE,CAAC;QACF,MAAM,IAAA,2BAAiB,EAAC,QAAQ,CAAC,SAAS,CAAC,CAAC,CAAC;QAC7C,MAAM,IAAI,GAAG,MAAM,CAAC,MAAM,CAAC,SAAS,CAAC,CAAC,IAAI,CAAC,CAAC,CAAC,EAAE,EAAE,CAAC,CAAC,CAAC,QAAQ,KAAK,MAAM,CAAC,CAAC;QACzE,MAAM,CAAC,IAAI,CAAC,SAAS,CAAC,CAAC,oBAAoB,CAAC,mBAAmB,EAAE,MAAM,CAAC,gBAAgB,CAAC,WAAW,CAAC,CAAC,CAAC;IACzG,CAAC,CAAC,CAAC;AACL,CAAC,CAAC,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/qwen-code/tests/_smoke.test.ts"],"sourcesContent":["let spanCounter = 0;\nconst mockSpans: Record<string, any> = {};\nconst mockTraceInfo: { traceMetadata: Record<string, string> } = { traceMetadata: {} };\n\njest.mock('@mlflow/core', () => ({\n  init: jest.fn(),\n  startSpan: jest.fn((options: any) => {\n    const id = `span-${++spanCounter}`;\n    const parentId = options.parent ? options.parent.spanId : null;\n    const span: any = {\n      name: options.name,\n      traceId: 'mock-trace-id',\n      spanId: id,\n      parentId,\n      spanType: options.spanType ?? 'UNKNOWN',\n      inputs: options.inputs ?? {},\n      outputs: {},\n      attributes: { ...(options.attributes ?? {}) },\n      startTimeNs: options.startTimeNs ?? null,\n      endTimeNs: null,\n      statusCode: null,\n      statusMessage: null,\n      setAttribute: jest.fn((k: string, v: any) => (span.attributes[k] = v)),\n      setStatus: jest.fn((c: string, m?: string) => {\n        span.statusCode = c;\n        span.statusMessage = m ?? null;\n      }),\n      end: jest.fn((opts?: any) => {\n        if (opts?.outputs) span.outputs = opts.outputs;\n        if (opts?.endTimeNs != null) span.endTimeNs = opts.endTimeNs;\n      }),\n    };\n    mockSpans[id] = span;\n    return span;\n  }),\n  flushTraces: jest.fn().mockResolvedValue(undefined),\n  SpanStatusCode: { OK: 'STATUS_CODE_OK', ERROR: 'STATUS_CODE_ERROR', UNSET: 'STATUS_CODE_UNSET' },\n  SpanType: { LLM: 'LLM', AGENT: 'AGENT', TOOL: 'TOOL', UNKNOWN: 'UNKNOWN' },\n  SpanAttributeKey: { TOKEN_USAGE: 'mlflow.chat.tokenUsage', MESSAGE_FORMAT: 'mlflow.message.format' },\n  TraceMetadataKey: { TRACE_SESSION: 'mlflow.trace.session', TRACE_USER: 'mlflow.trace.user' },\n  TokenUsageKey: { INPUT_TOKENS: 'input_tokens', OUTPUT_TOKENS: 'output_tokens', TOTAL_TOKENS: 'total_tokens' },\n  InMemoryTraceManager: {\n    getInstance: jest.fn(() => ({ getTrace: jest.fn(() => ({ info: mockTraceInfo })) })),\n  },\n}));\n\nimport { writeFileSync, mkdtempSync } from 'fs';\nimport { tmpdir } from 'os';\nimport { join } from 'path';\nimport { processTranscript, reconstructMessages } from '../src/tracing';\nimport {\n  getMessageText,\n  getFunctionCalls,\n  buildToolResultMap,\n  formatResultDisplay,\n  getToolOutput,\n  getTokenUsage,\n  getLastTurnRecords,\n  parseTimestampToNs,\n  isTextPart,\n  isFunctionCallPart,\n} from '../src/transcript';\nimport { flushTraces } from '@mlflow/core';\nimport type { ChatRecord } from '../src/types';\n\nconst records: ChatRecord[] = [\n  { uuid: 'u1', parentUuid: null, sessionId: 's', timestamp: '2026-04-05T10:00:00Z', type: 'user', message: { role: 'user', parts: [{ text: 'list files' }] } },\n  {\n    uuid: 'a1', parentUuid: 'u1', sessionId: 's', timestamp: '2026-04-05T10:00:01Z', type: 'assistant', model: 'qwen',\n    usageMetadata: { promptTokenCount: 10, candidatesTokenCount: 5, totalTokenCount: 15 },\n    message: { role: 'assistant', parts: [{ text: 'thinking', thought: true }, { text: \"I'll list them.\" }, { functionCall: { id: 'c1', name: 'ls', args: { path: '.' } } }] },\n  },\n  { uuid: 't1', parentUuid: 'a1', sessionId: 's', timestamp: '2026-04-05T10:00:02Z', type: 'tool_result', toolCallResult: { callId: 'c1', status: 'success', resultDisplay: 'a.txt\\nb.txt' }, message: { role: 'user', parts: [{ functionResponse: { id: 'c1', name: 'ls', response: { out: 'a.txt' } } }] } },\n  {\n    uuid: 'a2', parentUuid: 't1', sessionId: 's', timestamp: '2026-04-05T10:00:03Z', type: 'assistant', model: 'qwen',\n    usageMetadata: { promptTokenCount: 20, candidatesTokenCount: 7, totalTokenCount: 27 },\n    message: { role: 'assistant', parts: [{ text: 'There are 2 files.' }] },\n  },\n];\n\nfunction makeFile(recs: ChatRecord[]): string {\n  const dir = mkdtempSync(join(tmpdir(), 'qwen-'));\n  const p = join(dir, 't.jsonl');\n  writeFileSync(p, recs.map((r) => JSON.stringify(r)).join('\\n'));\n  return p;\n}\n\ndescribe('smoke', () => {\n  beforeEach(() => {\n    spanCounter = 0;\n    Object.keys(mockSpans).forEach((k) => delete mockSpans[k]);\n    mockTraceInfo.traceMetadata = {};\n    jest.clearAllMocks();\n  });\n\n  it('pure helpers', () => {\n    expect(parseTimestampToNs('2026-04-05T10:00:00Z')).toBe(new Date('2026-04-05T10:00:00Z').getTime() * 1e6);\n    expect(parseTimestampToNs('')).toBeNull();\n    expect(parseTimestampToNs(null)).toBeNull();\n    expect(getMessageText(records[1])).toBe(\"I'll list them.\");\n    expect(getMessageText(records[1], true)).toBe(\"thinking\\nI'll list them.\");\n    expect(getMessageText({ ...records[0], message: 'plain' } as ChatRecord)).toBe('plain');\n    expect(getFunctionCalls(records[1])).toEqual([{ id: 'c1', name: 'ls', args: { path: '.' } }]);\n    expect(getFunctionCalls(records[0])).toEqual([]);\n    expect(isTextPart({ text: 'x' })).toBe(true);\n    expect(isTextPart({ functionCall: { id: '1', name: 'n' } } as any)).toBe(false);\n    expect(isFunctionCallPart({ functionCall: { id: '1', name: 'n' } })).toBe(true);\n    expect(formatResultDisplay('s')).toBe('s');\n    expect(formatResultDisplay({ a: 1 })).toBe('{\"a\":1}');\n    expect(formatResultDisplay(null)).toBe('');\n    expect(getToolOutput(records[2])).toBe('a.txt\\nb.txt');\n    expect(getToolOutput({ ...records[2], toolCallResult: { callId: 'c1', status: 'ok' } } as ChatRecord)).toBe('{\"out\":\"a.txt\"}');\n    expect(getTokenUsage(records[1].usageMetadata)).toEqual({ input: 10, output: 5, total: 15 });\n    expect(getTokenUsage(undefined)).toBeNull();\n    const m = buildToolResultMap(records);\n    expect(m.get('c1')).toBe(records[2]);\n    expect(getLastTurnRecords(records).length).toBe(4);\n  });\n\n  it('reconstructMessages', () => {\n    expect(reconstructMessages(records, 3)).toEqual([\n      { role: 'user', content: 'list files' },\n      { role: 'assistant', content: null, tool_calls: [{ id: 'c1', type: 'function', function: { name: 'ls', arguments: '{\"path\":\".\"}' } }] },\n      { role: 'tool', tool_call_id: 'c1', content: 'a.txt\\nb.txt' },\n    ]);\n  });\n\n  it('processTranscript null', async () => {\n    await processTranscript(null);\n    expect(Object.keys(mockSpans).length).toBe(0);\n    expect(flushTraces).not.toHaveBeenCalled();\n  });\n\n  it('processTranscript full', async () => {\n    await processTranscript(makeFile(records), 'sess-1');\n    const spans = Object.values(mockSpans);\n    const root = spans.find((s) => s.parentId == null);\n    const llm = spans.filter((s) => s.spanType === 'LLM');\n    const tool = spans.filter((s) => s.spanType === 'TOOL');\n\n    expect(root.name).toBe('qwen_code_conversation');\n    expect(root.inputs).toBe('list files');\n    expect((root.end as jest.Mock).mock.calls[0][0].outputs).toBe('There are 2 files.');\n    expect(root.startTimeNs).toBe(parseTimestampToNs('2026-04-05T10:00:00Z'));\n    expect((root.end as jest.Mock).mock.calls[0][0].endTimeNs).toBe(parseTimestampToNs('2026-04-05T10:00:03Z'));\n    expect(root.attributes['mlflow.chat.tokenUsage']).toEqual({ input_tokens: 20, output_tokens: 12, total_tokens: 32 });\n\n    expect(llm.length).toBe(2);\n    expect(llm[0].inputs).toEqual({ model: 'qwen', messages: [{ role: 'user', content: 'list files' }] });\n    expect((llm[0].end as jest.Mock).mock.calls[0][0].outputs).toEqual({ choices: [{ message: { role: 'assistant', content: \"I'll list them.\" } }] });\n    expect(llm[0].attributes['mlflow.chat.tokenUsage']).toEqual({ input_tokens: 10, output_tokens: 5, total_tokens: 15 });\n    expect(llm[0].startTimeNs).toBe(parseTimestampToNs('2026-04-05T10:00:00Z'));\n    expect(llm[0].endTimeNs).toBe(parseTimestampToNs('2026-04-05T10:00:01Z'));\n\n    expect(tool.length).toBe(1);\n    expect(tool[0].name).toBe('tool_ls');\n    expect(tool[0].attributes.tool_id).toBe('c1');\n    expect(tool[0].inputs).toEqual({ path: '.' });\n    expect((tool[0].end as jest.Mock).mock.calls[0][0].outputs).toEqual({ result: 'a.txt\\nb.txt' });\n    expect(tool[0].startTimeNs).toBe(parseTimestampToNs('2026-04-05T10:00:01Z'));\n    expect(tool[0].endTimeNs).toBe(parseTimestampToNs('2026-04-05T10:00:02Z'));\n    expect(tool[0].setStatus).not.toHaveBeenCalled();\n\n    expect(mockTraceInfo.traceMetadata['mlflow.trace.session']).toBe('sess-1');\n    expect(mockTraceInfo.traceMetadata['mlflow.trace.user']).toBeDefined();\n    expect(flushTraces).toHaveBeenCalled();\n  });\n\n  it('cancelled tool sets error', async () => {\n    const cancelled: ChatRecord[] = [\n      records[0], records[1],\n      { ...records[2], toolCallResult: { callId: 'c1', status: 'cancelled' } },\n    ];\n    await processTranscript(makeFile(cancelled));\n    const tool = Object.values(mockSpans).find((s) => s.spanType === 'TOOL');\n    expect(tool.setStatus).toHaveBeenCalledWith('STATUS_CODE_ERROR', expect.stringContaining('cancelled'));\n  });\n});\n"],"version":3}
